from torch.utils.cpp_extension import load_inline

# CUDA kernel source code with shared memory optimization
matmul_shared_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16

__global__ void matmul_shared_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float sA[TILE_SIZE][TILE_SIZE];
    __shared__ float sB[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float sum = 0.0f;

    for (int k = 0; k < (N + TILE_SIZE - 1) / TILE_SIZE; k++) {
        // Load tile from A
        int a_col = k * TILE_SIZE + tx;
        if (row < N && a_col < N) {
            sA[ty][tx] = A[row * N + a_col];
        } else {
            sA[ty][tx] = 0.0f;
        }

        // Load tile from B
        int b_row = k * TILE_SIZE + ty;
        if (b_row < N && col < N) {
            sB[ty][tx] = B[b_row * N + col];
        } else {
            sB[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial product
        for (int i = 0; i < TILE_SIZE; i++) {
            sum += sA[ty][i] * sB[i][tx];
        }

        __syncthreads();
    }

    // Write result
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_shared_cuda(torch::Tensor A, torch::Tensor B) {
    // Check dimensions
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");
    int N = A.size(0);
    TORCH_CHECK(A.size(1) == N, "A must be square");
    TORCH_CHECK(B.size(0) == N, "B must be same size as A");
    TORCH_CHECK(B.size(1) == N, "B must be square");

    auto C = torch::zeros({N, N}, A.options());

    // Configure kernel launch parameters
    dim3 threadsPerBlock(TILE_SIZE, TILE_SIZE);
    dim3 numBlocks((N + TILE_SIZE - 1) / TILE_SIZE, 
                   (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_shared_kernel<<<numBlocks, threadsPerBlock>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
